function card(title,body,badge=''){return `<section class="pro-card"><div class="pro-card-head"><strong>${esc(title)}</strong>${badge?`<span>${esc(badge)}</span>`:''}</div>${body}</section>`;}
function field(label,id,type='text',attrs=''){return `<label class="pro-field"><span>${esc(label)}</span><input id="${id}" type="${type}" ${attrs}></label>`;}
function num3(prefix,labels=['X','Y','Z']){return `<div class="pro-axis-grid">${labels.map((x,i)=>field(x,`${prefix}${i}`,'number','step="0.01"')).join('')}</div>`;}
function setVals(prefix,vals,count=3){for(let i=0;i<count;i++){const e=$(`#${prefix}${i}`);if(e)e.value=Number.isFinite(+vals?.[i])?+vals[i]:'';}}
