function pushHistoryWithoutUiReset(s){
 if(!s)return s;
 // pushModelHistorySnapshot dispatches wc3-history-change synchronously.
 // The Pro UI used to rerender at that exact moment, overwriting the form
 // values before Apply could read them. Keep the history event, but suppress
 // this panel's render only for that synchronous transaction.
 pro.historyTransaction=true;
 try{I.pushModelHistorySnapshot?.(s);}finally{pro.historyTransaction=false;}
 return s;
}
function historyModel(label){return pushHistoryWithoutUiReset(I.captureModelEditSnapshot?.(label));}
function historyAnim(label){return pushHistoryWithoutUiReset(I.captureAnimationSnapshot?.(label));}
