function nodeById(id){return (model()?.nodes||[]).find(x=>String(x.id)===String(id));}
function seq(){return I.currentSequence?.()||null;}
function frameNow(){const s=seq();return s?Math.round(s.start+(s.end-s.start)*(state.animation?.t||0)):0;}
function bindTrack(node,tag,tr){node.tracks=node.tracks||{};node.tracks[tag]=tr;if(tag==='KGTR')node.translation=tr;if(tag==='KGRT')node.rotation=tr;if(tag==='KGSC')node.scaling=tr;}
function ensureTrack(node,tag){node.tracks=node.tracks||{};let tr=node.tracks[tag]||node[tag==='KGTR'?'translation':tag==='KGRT'?'rotation':'scaling'];if(!tr){tr={tag,interpolation:'Linear',interpolationType:1,globalSequenceId:-1,keys:[]};bindTrack(node,tag,tr);}return tr;}
function sampleTrack(tr,frame,def){if(!tr?.keys?.length)return [...def];const keys=[...tr.keys].sort((a,b)=>a.frame-b.frame);if(frame<=keys[0].frame)return [...(keys[0].value||def)];if(frame>=keys.at(-1).frame)return [...(keys.at(-1).value||def)];let a=keys[0],b=keys[1];for(let i=1;i<keys.length;i++){if(keys[i].frame>=frame){a=keys[i-1];b=keys[i];break;}}if((tr.interpolationType??1)===0)return [...(a.value||def)];const t=(frame-a.frame)/Math.max(1,b.frame-a.frame),av=a.value||def,bv=b.value||def;const out=def.map((_,i)=>n(av[i],def[i])+(n(bv[i],def[i])-n(av[i],def[i]))*t);if(out.length===4){const l=Math.hypot(...out)||1;return out.map(x=>x/l);}return out;}

