 const previousSelected=String(pro.assetSelected||''),previousPreviewPath=String(pro.assetPreviewPath||''),logicalPath=cleanWarcraftPath(previousPreviewPath||previousSelected),hadPreview=!!previousPreviewPath&&!!(pro.assetPreviewModel||pro.assetPreviewImage||pro.assetPreviewAudioUrl),view={...pro.assetPreviewView};
 pro.cascArtSet=next;try{localStorage.setItem('wc3.cascArtSet',next);}catch(_){}
 renderCascArtSetUi();
 if(!changed)return next;
 const reloadSeq=++pro.artSetReloadSeq;++pro.assetSearchSeq;++pro.gallerySearchSeq;++pro.galleryGeneration;++pro.assetPreviewSeq;
 pro.galleryResults=[];pro.galleryTotal=0;pro.galleryOffset=0;pro.gallerySelected='';pro.galleryTextureIntent='';
 pro.galleryThumbCache.clear();pro.galleryMeta.clear();pro.galleryParsed.clear();
 pro.galleryBaseQueue.length=0;pro.galleryTextureQueue.length=0;pro.galleryBaseQueued.clear();pro.galleryTextureQueued.clear();
 state.casc?.referenceTextures?.clear?.();
