function setGalleryCategory(category,{search=true}={}){const cfg=galleryCategoryConfig(category),changed=cfg.key!==pro.galleryCategory;pro.galleryCategory=cfg.key;renderGalleryCategoryUi();if(search&&changed)searchModelGallery({reset:true});return cfg.key;}
function updateGalleryCard(path){const card=galleryCardForPath(path);const rec=pro.galleryThumbCache.get(path),meta=pro.galleryMeta.get(path);if(card){card.classList.toggle('active',path===pro.gallerySelected);card.classList.toggle('is-loading',!rec||rec.state==='loading'||rec.state==='texture-loading');card.classList.toggle('is-error',rec?.state==='error');const img=card.querySelector('img'),badge=card.querySelector('[data-gallery-state]'),stats=card.querySelector('[data-gallery-stats]');if(img){if(rec?.url){img.src=rec.url;img.hidden=false;}else{img.removeAttribute('src');img.hidden=true;}}if(badge){badge.textContent=rec?.state==='textured'?'TEXTURED':rec?.state==='mesh'?'MESH':rec?.state==='texture-loading'?'TEXTURES':rec?.state==='error'?'ERROR':'LOADING';badge.classList.toggle('is-textured',rec?.state==='textured');}if(stats)stats.textContent=rec?.error?rec.error:galleryStatsText(meta);}updateGalleryProgress();}
function updateGalleryFooter(){const path=String(pro.gallerySelected||''),name=path?galleryFileName(path):'Nothing selected.',selected=$('#cascGallerySelected');if(selected){selected.textContent=name;selected.title=path;}for(const id of ['cascGalleryViewSelected','cascGalleryOpenSelected','cascGalleryExportSelected']){const b=$('#'+id);if(b)b.disabled=!path;}const more=$('#cascGalleryLoadMore');if(more){more.disabled=pro.galleryLoading||!pro.galleryResults.length||pro.galleryResults.length>=pro.galleryTotal;more.textContent=pro.galleryLoading?'Loading…':'Load more';}const counter=$('#cascGalleryCounter'),cat=galleryCategoryConfig();if(counter)counter.textContent=pro.galleryLoading&&!pro.galleryResults.length?`Loading ${cascArtSet().toUpperCase()} ${cat.label.toLowerCase()}…`:`Showing ${pro.galleryResults.length.toLocaleString()} / ${Math.max(pro.galleryTotal,pro.galleryResults.length).toLocaleString()} model files · ${cascArtSet().toUpperCase()} · ${cat.label}`;renderGalleryCategoryUi();updateGalleryProgress();}
function selectGalleryModel(path,{texture=true}={}){pro.gallerySelected=String(path||'');if(pro.gallerySelected)pro.assetSelected=pro.gallerySelected;if(texture)pro.galleryTextureIntent=pro.gallerySelected;for(const card of document.querySelectorAll('#cascModelGallery .casc-model-card'))card.classList.toggle('active',card.dataset.path===pro.gallerySelected);updateGalleryFooter();updateAssetActionUi();const parsed=pro.galleryParsed.get(pro.gallerySelected);if(texture&&parsed&&!pro.cascBridgeOverride&&pro.galleryTextureMode==='textured')queueGalleryTextureUpgrade(pro.gallerySelected,parsed,pro.galleryGeneration,{priority:true});return pro.gallerySelected;}
function ensureGalleryObserver(){if(pro.galleryObserver||!('IntersectionObserver'in window))return pro.galleryObserver;const root=$('#cascModelGallery');pro.galleryObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){const p=e.target?.dataset?.path;if(p)queueGalleryThumbnail(p);pro.galleryObserver.unobserve(e.target);}}, {root,rootMargin:'260px 80px',threshold:.01});return pro.galleryObserver;}
function ensureGalleryTextureObserver(){if(pro.galleryTextureMode!=='textured')return null;if(pro.galleryTextureObserver||!('IntersectionObserver'in window))return pro.galleryTextureObserver;const root=$('#cascModelGallery');pro.galleryTextureObserver=new IntersectionObserver(entries=>{for(const e of entries){const p=e.target?.dataset?.path;if(!p||!e.isIntersecting)continue;const m=pro.galleryParsed.get(p),rec=pro.galleryThumbCache.get(p);if(m&&rec?.state==='mesh'&&!pro.cascBridgeOverride&&pro.galleryTextureMode==='textured')queueGalleryTextureUpgrade(p,m,pro.galleryGeneration,{priority:p===pro.gallerySelected});if(rec?.state==='textured'||rec?.state==='error')pro.galleryTextureObserver.unobserve(e.target);}}, {root,rootMargin:'64px 40px',threshold:.01});return pro.galleryTextureObserver;}
function observeGalleryCard(card){const p=card?.dataset?.path,obs=ensureGalleryObserver(),texObs=ensureGalleryTextureObserver();if(obs)obs.observe(card);else if(p)queueGalleryThumbnail(p);if(texObs)texObs.observe(card);}
function queueGalleryPageThumbnails(){let added=0;for(const path of pro.galleryResults){const cached=pro.galleryThumbCache.get(path);if((cached&&cached.state!=='loading')||pro.galleryBaseQueued.has(path))continue;pro.galleryBaseQueued.add(path);pro.galleryThumbCache.set(path,{state:'loading',url:cached?.url||''});pro.galleryBaseQueue.push({path,generation:pro.galleryGeneration});added++;}if(added)scheduleGalleryBasePump();for(const path of pro.galleryResults)updateGalleryCard(path);updateGalleryProgress();return added;}
function renderModelGallery(){const h=$('#cascModelGallery');if(!h)return;pro.galleryObserver?.disconnect?.();pro.galleryTextureObserver?.disconnect?.();h.innerHTML='';if(!pro.galleryResults.length){h.innerHTML=`<div class="casc-gallery-empty">${pro.galleryLoading?'Reading Warcraft III model index…':'No models match this search.'}</div>`;updateGalleryFooter();return;}const frag=document.createDocumentFragment();for(const path of pro.galleryResults){const b=document.createElement('button');b.type='button';b.className='casc-model-card';b.dataset.path=path;b.title=path;b.innerHTML=`<span class="casc-model-thumb"><img alt="" hidden><span class="casc-model-thumb-state"><span data-gallery-state>LOADING</span></span></span><span class="casc-model-card-info"><strong>${esc(galleryFileName(path))}</strong><small>${esc(galleryFolder(path)||path)}</small><em data-gallery-stats>Waiting for preview…</em></span>`;b.addEventListener('click',()=>selectGalleryModel(path));b.addEventListener('dblclick',()=>{selectGalleryModel(path);galleryViewSelected();});frag.appendChild(b);}h.appendChild(frag);for(const card of h.querySelectorAll('.casc-model-card'))updateGalleryCard(card.dataset.path);queueGalleryPageThumbnails();updateGalleryFooter();}
async function searchModelGallery({reset=true}={}){const bridge=gameStorageBridge();if(!bridge?.searchAssets){status('This build does not expose CASC model search.');return false;}const q=String($('#cascGalleryQuery')?.value??pro.galleryQuery??'').trim(),requestId=++pro.gallerySearchSeq,offset=reset?0:pro.galleryResults.length,gen=reset?++pro.galleryGeneration:pro.galleryGeneration;pro.galleryLoading=true;pro.galleryQuery=q;if(reset){pro.galleryResults=[];pro.galleryTotal=0;pro.galleryOffset=0;pro.gallerySelected='';pro.galleryTextureIntent='';if(pro.galleryBasePumpTimer){clearTimeout(pro.galleryBasePumpTimer);pro.galleryBasePumpTimer=0;}if(pro.galleryTexturePumpTimer){clearTimeout(pro.galleryTexturePumpTimer);pro.galleryTexturePumpTimer=0;}pro.galleryBaseQueue.length=0;pro.galleryTextureQueue.length=0;pro.galleryBaseQueued.clear();pro.galleryTextureQueued.clear();for(const [path,rec] of [...pro.galleryThumbCache.entries()])if(rec?.state==='loading')pro.galleryThumbCache.delete(path);renderModelGallery();}updateGalleryFooter();try{const category=galleryCategoryConfig(),r=await bridge.searchAssets(q,category.type,pro.galleryPageSize,offset,cascArtSet());if(requestId!==pro.gallerySearchSeq||gen!==pro.galleryGeneration)return false;const rows=(r?.results||[]).filter(p=>/\.(mdx|mdl)$/i.test(p)),seen=new Set(pro.galleryResults.map(p=>p.toLowerCase()));for(const p of rows){const k=String(p).toLowerCase();if(!seen.has(k)){seen.add(k);pro.galleryResults.push(p);}}pro.galleryTotal=Math.max(pro.galleryResults.length,Number(r?.total)||pro.galleryResults.length);pro.galleryOffset=Number(r?.offset)||offset;if(reset&&!pro.gallerySelected&&pro.galleryResults.length)selectGalleryModel(pro.galleryResults[0],{texture:false});renderModelGallery();status(`CASC Model Gallery · ${cascArtSet().toUpperCase()} · ${category.label}: ${pro.galleryResults.length} / ${pro.galleryTotal} model(s)`);return true;}catch(e){if(requestId===pro.gallerySearchSeq){status(`Model Gallery search failed: ${e.message||e}`);if(reset)renderModelGallery();}return false;}finally{if(requestId===pro.gallerySearchSeq){pro.galleryLoading=false;updateGalleryFooter();}}}
function ensureModelGallery(){if(!pro.galleryResults.length&&!pro.galleryLoading)searchModelGallery({reset:true});else{renderModelGallery();updateGalleryFooter();}}
function galleryCanvasSet(){const w=normalizeThumbSize(pro.galleryThumbSize),h=thumbAspectHeight(w),cur=pro.galleryRenderCanvases;if(cur&&cur.width===w&&cur.height===h)return cur;const make=()=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c;};return pro.galleryRenderCanvases={width:w,height:h,flat:make(),gl:make(),overlay:make(),out:make()};}
function parseGalleryModel(path,ab){const core=window.WC3_MODEL_CORE;if(!core)throw new Error('WC3 model parser unavailable.');return /\.mdl$/i.test(path)?core.parseMDL(new TextDecoder().decode(ab),galleryFileName(path)):core.parseMDX(ab,galleryFileName(path));}
function scheduleGalleryBasePump(){if(pro.galleryBasePumpTimer||(pro.galleryBaseActive>0&&pro.galleryBaseActiveGeneration===pro.galleryGeneration))return;pro.galleryBasePumpTimer=setTimeout(()=>{pro.galleryBasePumpTimer=0;pumpGalleryBaseQueue();},12);}
function queueGalleryThumbnail(path){path=String(path||'');const cached=pro.galleryThumbCache.get(path);if(!path||(cached&&cached.state!=='loading')||pro.galleryBaseQueued.has(path))return;pro.galleryBaseQueued.add(path);pro.galleryThumbCache.set(path,{state:'loading',url:cached?.url||''});pro.galleryBaseQueue.push({path,generation:pro.galleryGeneration});updateGalleryCard(path);scheduleGalleryBasePump();}
function pumpGalleryBaseQueue(){if((pro.galleryBaseActive>0&&pro.galleryBaseActiveGeneration===pro.galleryGeneration)||!pro.galleryBaseQueue.length)return;const jobs=pro.galleryBaseQueue.splice(0,Math.max(1,pro.galleryBatchSize||12)),batchGeneration=jobs[0]?.generation??pro.galleryGeneration;pro.galleryBaseActive=jobs.length;pro.galleryBaseActiveGeneration=batchGeneration;loadGalleryBaseThumbnailBatch(jobs).finally(()=>{for(const job of jobs)pro.galleryBaseQueued.delete(job.path);if(pro.galleryBaseActiveGeneration===batchGeneration){pro.galleryBaseActive=0;if(pro.galleryBaseQueue.length)scheduleGalleryBasePump();}});}
async function loadGalleryBaseThumbnailBatch(jobs){const live=(jobs||[]).filter(job=>job&&job.generation===pro.galleryGeneration);if(!live.length)return;let result=null;try{const bridge=gameStorageBridge();if(!bridge?.readAssets)throw new Error('CASC read bridge unavailable.');const requests=live.map(job=>({path:job.path,kind:'model',artSet:cascArtSet(),candidates:[job.path]}));result=await bridge.readAssets(requests);const hits=Array.isArray(result?.results)?result.results:[];for(let i=0;i<live.length;i++){const job=live[i],path=job.path;if(job.generation!==pro.galleryGeneration)continue;try{const hit=hits.find(x=>Number(x?.requestIndex)===i)||hits.find(x=>String(x?.requestedPath||'').toLowerCase()===path.toLowerCase())||hits[i];if(!hit?.found)throw new Error('Model could not be read from CASC.');const ab=assetArrayBuffer(hit.data),full=parseGalleryModel(path,ab),meta=galleryModelStats(full,ab.byteLength),m=I.createGalleryThumbnailModel?I.createGalleryThumbnailModel(full):full;if(job.generation!==pro.galleryGeneration)continue;if(m?.galleryLiteStats)meta.lite=m.galleryLiteStats;if(m?.gallerySequence)meta.gallerySequence=m.gallerySequence;pro.galleryMeta.set(path,meta);galleryRememberParsed(path,m);if(pro.galleryTextureMode==='textured'&&!pro.cascBridgeOverride&&I.prepareReferenceModelRuntime&&I.drawRuntimeAssetPreview){pro.galleryThumbCache.set(path,{state:'texture-loading',url:''});updateGalleryCard(path);queueGalleryTextureUpgrade(path,m,job.generation,{priority:path===pro.galleryTextureIntent});}else{const c=galleryCanvasSet().flat;drawReferenceThumbnail(m,performance.now(),c,{gallery:true});const url=galleryDataUrl(c);if(!url)throw new Error('Thumbnail encoder failed.');if(job.generation!==pro.galleryGeneration)continue;pro.galleryThumbCache.set(path,{state:'mesh',url});updateGalleryCard(path);}}catch(e){if(job.generation!==pro.galleryGeneration)continue;pro.galleryThumbCache.set(path,{state:'error',url:'',error:String(e?.message||e).slice(0,90)});updateGalleryCard(path);}}}catch(e){for(const job of live){if(job.generation!==pro.galleryGeneration)continue;pro.galleryThumbCache.set(job.path,{state:'error',url:'',error:String(e?.message||e).slice(0,90)});updateGalleryCard(job.path);}}}
function scheduleGalleryTexturePump(delay=18){if(pro.galleryTexturePumpTimer||(pro.galleryTextureActive>0&&pro.galleryTextureActiveGeneration===pro.galleryGeneration))return;pro.galleryTexturePumpTimer=setTimeout(()=>{pro.galleryTexturePumpTimer=0;pumpGalleryTextureQueue();},delay);}
function queueGalleryTextureUpgrade(path,m,generation,{priority=false}={}){if(pro.galleryTextureMode!=='textured'||!I.prepareReferenceModelRuntime||!I.drawRuntimeAssetPreview)return;if(pro.galleryTextureQueued.has(path)){if(priority){const i=pro.galleryTextureQueue.findIndex(job=>job.path===path);if(i>0){const [job]=pro.galleryTextureQueue.splice(i,1);pro.galleryTextureQueue.unshift(job);}if(pro.galleryTexturePumpTimer){clearTimeout(pro.galleryTexturePumpTimer);pro.galleryTexturePumpTimer=0;}scheduleGalleryTexturePump(0);}return;}pro.galleryTextureQueued.add(path);const job={path,m,generation};if(priority)pro.galleryTextureQueue.unshift(job);else pro.galleryTextureQueue.push(job);scheduleGalleryTexturePump(priority?0:18);}
function pumpGalleryTextureQueue(){if((pro.galleryTextureActive>0&&pro.galleryTextureActiveGeneration===pro.galleryGeneration)||!pro.galleryTextureQueue.length)return;const jobs=pro.galleryTextureQueue.splice(0,Math.max(1,pro.galleryTextureBatchSize||4)),batchGeneration=jobs[0]?.generation??pro.galleryGeneration;pro.galleryTextureActive=jobs.length;pro.galleryTextureActiveGeneration=batchGeneration;upgradeGalleryThumbnailBatch(jobs).finally(()=>{for(const job of jobs)pro.galleryTextureQueued.delete(job.path);if(pro.galleryTextureActiveGeneration===batchGeneration){pro.galleryTextureActive=0;if(pro.galleryTextureQueue.length)scheduleGalleryTexturePump(18);}});}
function renderGalleryRuntime(path,runtime,generation){if(!runtime||generation!==pro.galleryGeneration)return false;const c=galleryCanvasSet(),now=performance.now();c.overlay.getContext('2d').clearRect(0,0,c.overlay.width,c.overlay.height);I.drawRuntimeAssetPreview(c.gl,c.overlay,runtime,now);const out=c.out,ctx=out.getContext('2d');ctx.clearRect(0,0,out.width,out.height);ctx.fillStyle='#090f15';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(c.gl,0,0,out.width,out.height);ctx.drawImage(c.overlay,0,0,out.width,out.height);const url=galleryDataUrl(out);if(!url||generation!==pro.galleryGeneration)return false;pro.galleryThumbCache.set(path,{state:'textured',url});updateGalleryCard(path);return true;}
async function upgradeGalleryThumbnailBatch(jobs){const live=(jobs||[]).filter(job=>job&&job.generation===pro.galleryGeneration);if(!live.length)return;const fail=(job,error='Texture runtime unavailable.')=>{if(job.generation!==pro.galleryGeneration)return;pro.galleryThumbCache.set(job.path,{state:'error',url:'',error:String(error||'Texture runtime unavailable.').slice(0,90)});updateGalleryCard(job.path);};try{if(I.prepareReferenceModelRuntimesBatch){const rows=await I.prepareReferenceModelRuntimesBatch(live.map(job=>({path:cleanWarcraftPath(job.path),model:job.m})),cascArtSet());const runtimes=new Map((rows||[]).map(x=>[cleanWarcraftPath(x.path),x.runtime]));for(const job of live){const runtime=runtimes.get(cleanWarcraftPath(job.path));if(runtime){if(!renderGalleryRuntime(job.path,runtime,job.generation))fail(job,'Texture preview render failed.');}else fail(job);}return;}for(const job of live){try{const runtime=await I.prepareReferenceModelRuntime(job.m,cleanWarcraftPath(job.path),cascArtSet());if(!runtime||!renderGalleryRuntime(job.path,runtime,job.generation))fail(job,'Texture preview render failed.');}catch(e){fail(job,e?.message||e);}}}catch(e){for(const job of live)fail(job,e?.message||e);}}
