function clearGalleryThumbnailWork({keepParsed=true}={}){
 pro.galleryGeneration++;if(pro.galleryBasePumpTimer){clearTimeout(pro.galleryBasePumpTimer);pro.galleryBasePumpTimer=0;}if(pro.galleryTexturePumpTimer){clearTimeout(pro.galleryTexturePumpTimer);pro.galleryTexturePumpTimer=0;}pro.galleryBaseQueue.length=0;pro.galleryTextureQueue.length=0;pro.galleryBaseQueued.clear();pro.galleryTextureQueued.clear();pro.galleryBaseActive=0;pro.galleryTextureActive=0;pro.galleryThumbCache.clear();pro.galleryRenderCanvases=null;if(!keepParsed){pro.galleryMeta.clear();pro.galleryParsed.clear();}pro.galleryObserver?.disconnect?.();pro.galleryTextureObserver?.disconnect?.();renderModelGallery();
}
