function applyMaterial(){const m=model(),mat=m?.materials?.[pro.material],l=mat?.layers?.[pro.layer];if(!m||!mat||!l)return;historyModel('Edit material');l.filterModeId=iv($('#proFilter').value,0);l.filterMode=FILTERS[l.filterModeId]||'None';l.alpha=clamp(n($('#proAlpha').value,1),0,1);l.emissiveGain=n($('#proEmissive').value,1);mat.shader=String($('#proShader').value||'').slice(0,79);l.flags=iv(l.flags,0)&~(1|16|32|64|128|256);if($('#proUnshaded').checked)l.flags|=1;if($('#proTwoSided').checked)l.flags|=16;if($('#proUnfogged').checked)l.flags|=32;if($('#proNoDepthTest').checked)l.flags|=64;if($('#proNoDepthWrite').checked)l.flags|=128;if($('#proUnlit').checked)l.flags|=256;l.twoSided=!!(l.flags&16);l.unshaded=!!(l.flags&1);l.textureSlots=l.textureSlots||{};for(let slot=0;slot<6;slot++){const tid=iv($(`#proSlot${slot}`)?.value,-1);if(tid>=0)l.textureSlots[slot]=tid;else delete l.textureSlots[slot];if(slot===0&&tid>=0)l.textureId=tid;}l.normalTextureId=l.textureSlots[1]??-1;l.ormTextureId=l.textureSlots[2]??-1;l.emissiveTextureId=l.textureSlots[3]??-1;l.teamColorTextureId=l.textureSlots[4]??-1;l.reflectionsTextureId=l.textureSlots[5]??-1;mat.textureId=l.textureId;m.__materialEdited=true;dirty();}

function renderOutliner(){const h=$('#proOutliner');if(!h)return;const m=model();if(!m){h.innerHTML='<div class="pro-empty">No model loaded.</div>';return;}const q=pro.outlinerFilter.toLowerCase();const groups=[['Geosets',(m.geosets||[]).map((g,i)=>({kind:'geo',id:i,name:`Geoset ${i+1}`,meta:`Material ${g.materialId}`}))],['Bones / Helpers',rigNodes().map(x=>({kind:'node',id:x.id,name:x.name||x.type,meta:`${x.type} · ${x.id}`}))],['Materials',(m.materials||[]).map((x,i)=>({kind:'mat',id:i,name:`Material ${x.id??i}`,meta:`${(x.layers||[]).length} layer(s)`}))],['Cameras',(m.cameras||[]).map((x,i)=>({kind:'cam',id:i,name:x.name||`Camera ${i+1}`,meta:'Camera'}))],['Effects',(m.nodes||[]).filter(x=>['ParticleEmitter2','ParticleEmitter','ParticleEmitterPopcorn','RibbonEmitter','Attachment','EventObject','Light'].includes(x.type)).map(x=>({kind:'node',id:x.id,name:x.name||x.type,meta:x.type}))]];h.innerHTML='';for(const [name,items0] of groups){const items=items0.filter(x=>!q||`${x.name} ${x.meta}`.toLowerCase().includes(q));if(!items.length)continue;const g=document.createElement('div');g.className='pro-tree-group';g.innerHTML=`<div class="pro-tree-head">${esc(name)} <span>${items.length}</span></div>`;for(const it of items){const row=document.createElement('button');row.type='button';row.className='pro-tree-row';let eye='';if(it.kind==='geo')eye=state.hiddenGeosets?.has(it.id)?'◌':'●';row.innerHTML=`<span class="pro-tree-eye">${eye}</span><span><strong>${esc(it.name)}</strong><small>${esc(it.meta)}</small></span>`;row.addEventListener('click',(ev)=>{if(it.kind==='geo'&&ev.target.closest('.pro-tree-eye')){const snap=I.captureModelEditSnapshot?.('Geoset visibility');if(state.hiddenGeosets?.has(it.id))state.hiddenGeosets.delete(it.id);else state.hiddenGeosets?.add(it.id);if(snap)I.pushModelHistorySnapshot?.(snap);I.markDirty?.();renderOutliner();return;}selectOutliner(it);});g.appendChild(row);}h.appendChild(g);}}
function selectOutliner(it){if(it.kind==='geo'){I.selectGeoset?.(it.id);activateProp('geosets');}else if(it.kind==='node'){state.selectedNodeId=it.id;I.focusNodeInViewport?.(it.id);if(nodeById(it.id)?.type==='Bone'||nodeById(it.id)?.type==='Helper'){pro.rigNode=it.id;activateProp('rig');}else activateProp('effects');}else if(it.kind==='mat'){pro.material=it.id;pro.layer=0;activateProp('materials');}else if(it.kind==='cam'){const c=model()?.cameras?.[it.id];if(c){state.selectedNodeId=c.__cameraId||`C${it.id}`;activateProp('author');}}renderAllPro();}

async function openCompare(file){if(!file)return;try{const buf=await file.arrayBuffer(),core=window.WC3_MODEL_CORE,parsed=/\.mdl$/i.test(file.name)?core.parseMDL(new TextDecoder().decode(buf),file.name):core.parseMDX(buf,file.name);pro.compareModel=parsed;pro.compareName=file.name;renderCompare();status(`Comparison model loaded: ${file.name}`);}catch(e){status(`Compare load failed: ${e.message||e}`);}}
function renderCompare(){const e=$('#proCompareInfo'),sel=$('#proCompareAction');if(!e||!sel)return;const a=model(),b=pro.compareModel;if(!a||!b){e.textContent=b?'Load a target model to compare.':'No comparison model loaded.';sel.innerHTML='';return;}const rows=[['Geosets',a.geosets?.length||0,b.geosets?.length||0],['Textures',a.textureDefs?.length||0,b.textureDefs?.length||0],['Materials',a.materials?.length||0,b.materials?.length||0],['Sequences',a.sequences?.length||0,b.sequences?.length||0],['Bones',a.bones?.length||0,b.bones?.length||0],['Helpers',a.helpers?.length||0,b.helpers?.length||0],['FX',a.particleEmitters2?.length||0,b.particleEmitters2?.length||0]];e.innerHTML=`<strong>${esc(pro.compareName)}</strong><div class="pro-compare-grid">${rows.map(r=>`<span>${r[0]}</span><b>${r[1]}</b><b>${r[2]}</b><em>${r[2]-r[1]>=0?'+':''}${r[2]-r[1]}</em>`).join('')}</div>`;sel.innerHTML=(b.sequences||[]).map((s,i)=>`<option value="${i}">${esc(s.name)} · ${s.start}–${s.end}</option>`).join('');}
function importAction(){const a=model(),b=pro.compareModel,si=iv($('#proCompareAction').value,-1),src=b?.sequences?.[si];if(!a||!b||!src)return;historyAnim('Import action');const maxEnd=Math.max(0,...(a.sequences||[]).map(s=>s.end||0)),gap=100,start=maxEnd+gap,end=start+(src.end-src.start),id=(a.sequences||[]).length,newSeq={...clone(src),id,name:`${src.name} Import`,start,end,length:end-start};a.sequences=a.sequences||[];a.sequences.push(newSeq);const destByName=new Map((a.nodes||[]).map(x=>[`${x.type}|${String(x.name||'').toLowerCase()}`,x]));let copied=0;for(const sn of b.nodes||[]){const dn=destByName.get(`${sn.type}|${String(sn.name||'').toLowerCase()}`);if(!dn)continue;for(const tag of ['KGTR','KGRT','KGSC']){const st=sn.tracks?.[tag];if(!st?.keys?.length)continue;const segment=st.keys.filter(k=>k.frame>=src.start&&k.frame<=src.end);if(!segment.length)continue;const dt=ensureTrack(dn,tag);dt.interpolation=st.interpolation;dt.interpolationType=st.interpolationType;for(const k of segment)dt.keys.push({...clone(k),frame:start+(k.frame-src.start)});dt.keys.sort((x,y)=>x.frame-y.frame);copied+=segment.length;}}
a.__animationEdited=true;a.__animationKeyEdited=true;dirty();const seqSel=$('#modelSequenceSelect');if(seqSel){seqSel.value=String(id);seqSel.dispatchEvent(new Event('change'));}status(`Imported ${src.name}: ${copied} keyframes mapped by node name/type`);}
function analyze(){const m=model(),e=$('#proAnalyzeResult');if(!m||!e)return;const usedTex=new Set();for(const mat of m.materials||[])for(const l of mat.layers||[]){if(iv(l.textureId,-1)>=0)usedTex.add(iv(l.textureId));for(const v of Object.values(l.textureSlots||{}))if(iv(v,-1)>=0)usedTex.add(iv(v));}for(const p of m.particleEmitters2||[])if(iv(p.textureId,-1)>=0)usedTex.add(iv(p.textureId));const unused=(m.textureDefs||[]).map((x,i)=>i).filter(i=>!usedTex.has(i));const duplicateSeq=[];const seen=new Set();for(const s of m.sequences||[]){const k=String(s.name||'').toLowerCase();if(seen.has(k))duplicateSeq.push(s.name);seen.add(k);}const orphanGA=(m.geosetAnimations||[]).filter(x=>iv(x.geosetId,-1)>=0&&iv(x.geosetId)>= (m.geosets?.length||0));const badParent=rigNodes().filter(x=>x.parentId>=0&&!nodeById(x.parentId));e.textContent=`Unused textures: ${unused.length}${unused.length?` [${unused.join(', ')}]`:''}\nDuplicate action names: ${duplicateSeq.length}${duplicateSeq.length?` [${duplicateSeq.join(', ')}]`:''}\nOrphan GeosetAnim: ${orphanGA.length}\nInvalid rig parents: ${badParent.length}\nUnknown chunks preserved: ${(m.unknownChunks||[]).length}\nFormat: ${m.type} v${m.formatVersion}`;}
function cleanup(){const m=model();if(!m)return;analyze();const used=new Set();for(const mat of m.materials||[])for(const l of mat.layers||[]){if(iv(l.textureId,-1)>=0)used.add(iv(l.textureId));for(const v of Object.values(l.textureSlots||{}))if(iv(v,-1)>=0)used.add(iv(v));}for(const p of m.particleEmitters2||[])if(iv(p.textureId,-1)>=0)used.add(iv(p.textureId));let cut=(m.textureDefs||[]).length;while(cut>0&&!used.has(cut-1))cut--;if(cut===(m.textureDefs||[]).length){status('Safe Cleanup: no trailing unused texture slots found.');return;}historyModel('Safe cleanup');m.textureDefs=m.textureDefs.slice(0,cut);if(Array.isArray(m.textures))m.textures=m.textures.slice(0,cut);state.textures=state.textures.slice(0,cut);m.__textureEdited=true;dirty();status(`Safe Cleanup removed trailing unused texture slots · now ${cut}`);}


const RECENT_KEY='wc3as-v13-recent-models';
function recentModels(){try{return (JSON.parse(localStorage.getItem(RECENT_KEY)||'[]')||[]).filter(x=>x&&x.path).slice(0,12);}catch(_){return[];}}
function rememberRecentModel(){const m=model(),path=String(m?.sourcePath||'');if(!path||path===pro.recentModelKey)return;pro.recentModelKey=path;let rows=recentModels().filter(x=>x.path.toLowerCase()!==path.toLowerCase());rows.unshift({path,name:m.sourceName||path.split(/[\\/]/).pop(),openedAt:Date.now()});localStorage.setItem(RECENT_KEY,JSON.stringify(rows.slice(0,12)));renderRecentModels();}
