async function openRecentModel(path){try{const bridge=window.WC3_FILE_ASSOCIATIONS;if(!bridge?.readFile)throw new Error('Windows file bridge unavailable.');const p=await bridge.readFile(path);if(!p?.ok)throw new Error(p?.error||'File no longer exists.');const file=new File([p.data],p.name,{type:p.ext==='.mdl'?'text/plain':'application/octet-stream'});await API.openModel(file,[],{sourcePath:p.path});status(`Recent model opened: ${p.name}`);}catch(e){status(`Recent model failed: ${e.message||e}`);}}
async function batchAnalyze(files){const list=[...(files||[])];if(!list.length)return [];const out=$('#proBatchResult');pro.batchRows=[];if(out)out.textContent=`Analyzing ${list.length} model(s)…`;for(const file of list){try{const ab=await file.arrayBuffer(),m=/\.mdl$/i.test(file.name)?window.WC3_MODEL_CORE.parseMDL(new TextDecoder().decode(ab),file.name):window.WC3_MODEL_CORE.parseMDX(ab,file.name),tri=(m.geosets||[]).reduce((a,g)=>a+Math.floor((g.faces||[]).length/3),0),hd=(m.geosets||[]).some(g=>(g.skin||[]).length);pro.batchRows.push({name:file.name,size:file.size,type:m.type||'',version:m.formatVersion||m.version||800,geosets:(m.geosets||[]).length,triangles:tri,textures:(m.textureDefs||m.textures||[]).length,materials:(m.materials||[]).length,sequences:(m.sequences||[]).length,bones:(m.bones||[]).length,fx:(m.particleEmitters2||[]).length,profile:hd?'HD/Reforged':'SD/Classic',status:'OK'});}catch(e){pro.batchRows.push({name:file.name,size:file.size,status:`ERROR: ${e.message||e}`});}}renderBatch();return pro.batchRows.map(x=>({...x}));}
function renderBatch(){const e=$('#proBatchResult');if(!e)return;if(!pro.batchRows.length){e.textContent='Select multiple MDX/MDL files to compare structure, size and compatibility.';return;}e.textContent=pro.batchRows.map(r=>r.status==='OK'?`${r.name} · ${r.type} v${r.version} · ${r.profile} · ${(r.size/1048576).toFixed(2)} MB · ${r.geosets} geo · ${r.triangles.toLocaleString()} tris · ${r.sequences} anim · ${r.bones} bones · ${r.fx} FX`:`${r.name} · ${r.status}`).join('\n');}
