function workspaceEditableState(m){return {
  sequences:clone(m.sequences||[]),nodes:clone(m.nodes||[]),materials:clone(m.materials||[]),cameras:clone(m.cameras||[]),pivots:clone(m.pivots||[]),textureDefs:clone(m.textureDefs||[]),textures:clone(m.textures||[]),
  geosets:clone(m.geosets||[]),geosetAnimations:clone(m.geosetAnimations||[]),animationOps:clone(m.__animationOps||[]),
  flags:{animationEdited:!!m.__animationEdited,animationKeyEdited:!!m.__animationKeyEdited,rigEdited:!!m.__rigEdited,materialEdited:!!m.__materialEdited,cameraEdited:!!m.__cameraEdited,effectsEdited:!!m.__effectsEdited,geometryEdited:!!m.__geometryEdited,textureEdited:!!m.__textureEdited,geosetStructureEdited:!!m.__geosetStructureEdited}
};}
async function buildProjectBlob(){const m=model();if(!m?.sourceBuffer)throw new Error('Load a model before saving a workspace project.');const base=String(m.sourceName||'model.mdx').split(/[\\/]/).pop();const files=[{name:`model/${base}`,data:bufferBytes(m.sourceBuffer)}],tex=[];for(let i=0;i<state.textures.length;i++){const slot=state.textures[i];if(!slot?.canvas)continue;const data=await canvasPngBytes(slot.canvas);if(!data)continue;const ref=String(m.textureDefs?.[i]?.path||slot.ref||`texture_${i}.blp`),stem=(ref.split(/[\\/]/).pop()||`texture_${i}`).replace(/\.[^.]+$/,'');const file=`textures/${String(i).padStart(3,'0')}_${stem}.png`;files.push({name:file,data});tex.push({index:i,file,ref});}
 const meta={format:'WC3AssetStudioProject',version:1,appVersion:'1.4',created:new Date().toISOString(),sourceName:base,edit:workspaceEditableState(m),textures:tex,ui:{camera:clone(state.camera),selectedNodeId:state.selectedNodeId,selectedGeosetIndex:state.selectedGeosetIndex,hiddenGeosets:[...state.hiddenGeosets],activePropPanel:state.activePropPanel}};files.unshift({name:'project.json',data:JSON.stringify(meta)});if(!window.SimpleZip?.create)throw new Error('ZIP project writer is unavailable.');return window.SimpleZip.create(files);}
async function saveProjectFile(){try{const blob=await buildProjectBlob(),m=model(),base=String(m.sourceName||'model').replace(/\.(mdx|mdl)$/i,'');const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${base}.wc3asset`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);status('Workspace project saved.');}catch(e){status(`Project save failed: ${e.message||e}`);}}
