async function restoreProjectBlob(blobOrFile){const ab=await blobOrFile.arrayBuffer(),entries=await window.WC3_MODEL_CORE.unzipEntries(ab),map=entryMap(entries),metaEntry=map.get('project.json');if(!metaEntry)throw new Error('project.json was not found in this .wc3asset file.');const meta=JSON.parse(new TextDecoder().decode(metaEntry.data));if(meta.format!=='WC3AssetStudioProject')throw new Error('Not a WC3 Asset Studio workspace project.');const sourceEntry=map.get(`model/${meta.sourceName}`)||[...map.entries()].find(([k])=>/^model\/.+\.(mdx|mdl)$/i.test(k))?.[1];if(!sourceEntry)throw new Error('Project model source is missing.');const textureFiles=[];for(const t of meta.textures||[]){const e=map.get(t.file);if(!e)continue;const refName=(String(t.ref||'texture.blp').split(/[\\/]/).pop()||'texture.blp').replace(/\.[^.]+$/,'.png');textureFiles.push(fileFromEntry(e,refName));}await API.openModel(fileFromEntry(sourceEntry,meta.sourceName||'project.mdx'),textureFiles,{sourcePath:''});const m=model(),ed=meta.edit||{};for(const k of ['sequences','nodes','materials','cameras','pivots','textureDefs','textures','geosets','geosetAnimations'])if(ed[k])m[k]=clone(ed[k]);m.__animationOps=clone(ed.animationOps||[]);const f=ed.flags||{};m.__animationEdited=!!f.animationEdited;m.__animationKeyEdited=!!f.animationKeyEdited;m.__rigEdited=!!f.rigEdited;m.__materialEdited=!!f.materialEdited;m.__cameraEdited=!!f.cameraEdited;m.__effectsEdited=!!f.effectsEdited;m.__geometryEdited=!!f.geometryEdited;m.__textureEdited=!!f.textureEdited;m.__geosetStructureEdited=!!f.geosetStructureEdited;I.rebuildNodeTypeArrays?.();const ui=meta.ui||{};if(ui.camera)Object.assign(state.camera,ui.camera);state.selectedNodeId=ui.selectedNodeId??-1;state.selectedGeosetIndex=ui.selectedGeosetIndex??-1;state.hiddenGeosets=new Set(ui.hiddenGeosets||[]);I.invalidateGeometryCache?.();I.invalidatePickCache?.();I.renderEverything?.();if(ui.activePropPanel)setTimeout(()=>activateProp(ui.activePropPanel),0);status(`Workspace restored: ${meta.sourceName}`);}
async function loadProjectFile(file){if(!file)return;try{await restoreProjectBlob(file);}catch(e){status(`Project load failed: ${e.message||e}`);}}
function recoveryDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('WC3AssetStudioRecovery',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('recovery'))req.result.createObjectStore('recovery',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
