async function saveRecovery(){if(!model())return;try{status('Saving recovery snapshot…');await putRecovery(await buildProjectBlob());status('Recovery snapshot saved.');}catch(e){status(`Recovery save failed: ${e.message||e}`);}}
async function restoreRecovery(){try{const rec=await getRecovery();if(!rec?.blob){status('No recovery snapshot found.');return;}await restoreProjectBlob(rec.blob);}catch(e){status(`Recovery restore failed: ${e.message||e}`);}}
async function renderRecoveryInfo(){const el=$('#proRecoveryInfo');if(!el)return;try{const r=await getRecovery();el.textContent=r?`Latest recovery: ${r.sourceName||'model'} · ${new Date(r.savedAt).toLocaleString()}`:'No recovery snapshot saved.';}catch(e){el.textContent='Recovery database is unavailable.';}}
let recoveryTimer=0;function scheduleRecoveryTimer(){if(recoveryTimer)clearInterval(recoveryTimer);const p=getPrefs();if(p.autosave)recoveryTimer=setInterval(()=>{if(model())saveRecovery();},5*60*1000);}

