 $$('[data-pro-asset-mode]').forEach(b=>b.classList.toggle('active',b.dataset.proAssetMode===mode));
 const hints={units:'Search units / heroes / creatures / buildings…','model-units':'Search non-hero unit models…',heroes:'Search Warcraft heroes…',buildings:'Search Warcraft buildings…',doodads:'Search doodads / props…',effects:'Search spells / particles / effects…',projectiles:'Search missiles / projectiles…',items:'Search item models…',environment:'Search environment / terrain models…',portraits:'Search portrait models…',models:'Search any Warcraft MDX / MDL…',textures:'Search Warcraft textures…',sounds:'Search Warcraft sounds / music / voice…'};
