 const preview=$('#proAssetPreview'),ref=$('#proAssetReference'),attach=$('#proAssetAttach'),importBtn=$('#proAssetUseTexture'),paint=$('#proAssetLoadPaint'),exp=$('#proAssetExport'),deps=$('#proAssetExportDeps');
 if(preview)preview.disabled=!path;
