 if(ref){ref.disabled=!isModel;ref.textContent=unitMode?'ADD UNIT BESIDE MODEL':'ADD BESIDE MODEL';}
 if(attach){attach.disabled=!isModel||unitMode;attach.textContent=mode==='effects'||mode==='projectiles'?'INSERT EFFECT':unitMode?'REFERENCE ONLY':'INSERT AS ATTACHMENT';attach.title=unitMode?'Units, heroes and buildings are loaded beside the target as reference models. Use EFFECTS / MISSILES for effect insertion.':'';}
