async function attachSelectedAsset(){
  if(!/\.(mdx|mdl)$/i.test(pro.assetSelected)){status('Select a Warcraft model/effect asset first.');return;}
  const p=cleanWarcraftPath(pro.assetSelected);
  try{
    if(state.casc){state.casc.enabled=true;state.casc.userRequested=true;}
    const toggle=$('#modelUseCascEffects');if(toggle)toggle.checked=true;
    status(`Connecting Warcraft assets for: ${p}`);
    await I.ensureCascOnDemand?.({enableEffects:true,resolveTextures:true,reason:'asset-browser-attachment'});
    const node=await API.addEffectAttachmentFromPath?.(p,p.split('\\').pop().replace(/\.(mdx|mdl)$/i,''));
    await I.loadCascEffectAssets?.(true);
    status(node?`Attachment added and preview loaded: ${p}`:`Attachment could not be created: ${p}`);if(node){window.WC3_WORKSPACE_UI?.openModule?.('model');activateProp('effects');}
  }catch(e){status(`Attachment import failed: ${e.message||e}`);}
}

