function shortcutHandler(e){if(document.body.dataset.module!=='model'||e.ctrlKey||e.metaKey)return;const t=e.target;if(t&&(/INPUT|TEXTAREA|SELECT/.test(t.tagName)||t.isContentEditable))return;const k=e.key.toLowerCase();if(k==='g'){state.activePropPanel='geosets';const b=$('[data-model-geoset-tool="move"]');b?.click();e.preventDefault();}else if(k==='r'){const b=$('[data-model-geoset-tool="rotate"]');b?.click();e.preventDefault();}else if(k==='s'){const b=$('[data-model-geoset-tool="scale"]');b?.click();e.preventDefault();}else if(k==='f'){if(state.selectedNodeId>=0)I.focusNodeInViewport?.(state.selectedNodeId,{fit:true});else if(state.selectedGeosetIndex>=0)$('#modelGeosetFocusBtn')?.click();e.preventDefault();}else if(k==='h'&&!e.altKey){$('#modelGeosetHideBtn')?.click();e.preventDefault();}else if(k==='h'&&e.altKey){$('#modelGeosetShowAllBtn')?.click();e.preventDefault();}else if(e.shiftKey&&k==='d'){$('#modelGeosetCloneBtn')?.click();e.preventDefault();}}


function setCascBridgeForAutoTest(bridge=null){pro.cascBridgeOverride=bridge||null;return gameStorageBridge();}
function setAssetFixtureForAutoTest(fixture={}){
 if(Object.prototype.hasOwnProperty.call(fixture,'results'))pro.assetResults=Array.isArray(fixture.results)?[...fixture.results]:[];
 if(Object.prototype.hasOwnProperty.call(fixture,'selected'))pro.assetSelected=String(fixture.selected||'');
 if(Object.prototype.hasOwnProperty.call(fixture,'previewPath'))pro.assetPreviewPath=String(fixture.previewPath||'');
 if(Object.prototype.hasOwnProperty.call(fixture,'previewModel'))pro.assetPreviewModel=fixture.previewModel||null;
 if(Object.prototype.hasOwnProperty.call(fixture,'previewRuntime'))pro.assetPreviewRuntime=fixture.previewRuntime||null;
 if(Object.prototype.hasOwnProperty.call(fixture,'previewImage'))pro.assetPreviewImage=fixture.previewImage||null;
 renderAssetResults();updateAssetActionUi();return {...pro};
}
function setGalleryFixtureForAutoTest(fixture={}){
 // Deterministic fixtures must own the gallery completely. Obsolete any real
 // CASC search still finishing from an earlier test and clear its loading flag.
 if(fixture.clearCache||Object.prototype.hasOwnProperty.call(fixture,'results')){pro.gallerySearchSeq++;pro.galleryLoading=false;}
 if(Object.prototype.hasOwnProperty.call(fixture,'results'))pro.galleryResults=Array.isArray(fixture.results)?[...fixture.results]:[];
 if(Object.prototype.hasOwnProperty.call(fixture,'total'))pro.galleryTotal=Math.max(0,Number(fixture.total)||0);
 if(Object.prototype.hasOwnProperty.call(fixture,'selected'))pro.gallerySelected=String(fixture.selected||'');
 if(Object.prototype.hasOwnProperty.call(fixture,'category'))pro.galleryCategory=galleryCategoryConfig(String(fixture.category||'all')).key;
 if(fixture.clearCache){pro.galleryGeneration++;if(pro.galleryBasePumpTimer){clearTimeout(pro.galleryBasePumpTimer);pro.galleryBasePumpTimer=0;}if(pro.galleryTexturePumpTimer){clearTimeout(pro.galleryTexturePumpTimer);pro.galleryTexturePumpTimer=0;}pro.galleryThumbCache.clear();pro.galleryMeta.clear();pro.galleryParsed.clear();pro.galleryBaseQueue.length=0;pro.galleryTextureQueue.length=0;pro.galleryBaseQueued.clear();pro.galleryTextureQueued.clear();pro.galleryBaseActive=0;pro.galleryTextureActive=0;}
 renderModelGallery();updateGalleryFooter();renderGalleryCategoryUi();return {results:[...pro.galleryResults],total:pro.galleryTotal,selected:pro.gallerySelected,category:pro.galleryCategory};
}
function gallerySnapshotForAutoTest(){return{view:pro.cascView,results:[...pro.galleryResults],total:pro.galleryTotal,selected:pro.gallerySelected,category:pro.galleryCategory,searchType:galleryCategoryConfig().type,loading:pro.galleryLoading,progress:galleryProgressStats(),thumbs:[...pro.galleryThumbCache.entries()].map(([path,v])=>({path,state:v.state,hasUrl:!!v.url,error:v.error||''})),meta:[...pro.galleryMeta.entries()].map(([path,v])=>({path,...v})),parsed:[...pro.galleryParsed.entries()].map(([path,m])=>({path,galleryLite:!!m?.galleryLite,sequence:m?.gallerySequence||'',geosets:(m?.geosets||[]).length,textures:(m?.textureDefs||[]).length,nodes:(m?.nodes||[]).length,sequences:(m?.sequences||[]).length,particleEmitters2:(m?.particleEmitters2||[]).length}))};}

